import type { Order, OrderRepo } from "../../src/orders/orderRepo";

export class InMemoryOrderRepo implements OrderRepo {
  private rows = new Map<string, Order>();
  public saves: Order[] = [];

  async findById(id: string): Promise<Order | undefined> {
    return this.rows.get(id);
  }

  async save(order: Order): Promise<void> {
    this.saves.push(structuredClone(order));
    this.rows.set(order.id, structuredClone(order));
  }

  seed(...orders: Order[]): this {
    for (const o of orders) this.rows.set(o.id, o);
    return this;
  }
}

/** Split `items` into arrays of at most `size` elements. */
export function chunk<T>(items: readonly T[], size: number): T[][] {
  if (!Number.isInteger(size) || size < 1) {
    throw new RangeError(`chunk size must be a positive integer, got ${size}`);
  }
  const out: T[][] = [];
  for (let i = 0; i < items.length; i += size) {
    out.push(items.slice(i, i + size));
  }
  return out;
}

import { type Locator, type Page, expect } from "@playwright/test";

export class LoginPage {
  readonly email: Locator;
  readonly password: Locator;
  readonly submit: Locator;

